<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
$user=require_auth(); $error=null; $success=null;
function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function role_label(string $r):string{return ['admin'=>'مدیر','teacher'=>'مدرس','student'=>'دانش‌آموز'][$r]??$r;}
function dt(?string $v):string{if(!$v)return 'تعیین نشده';$t=strtotime($v);return $t?date('Y/m/d - H:i',$t):$v;}
$pdo=db(); $hasStarts=(bool)$pdo->query("SHOW COLUMNS FROM classes LIKE 'starts_at'")->fetch(); $hasRequests=(bool)$pdo->query("SHOW TABLES LIKE 'class_join_requests'")->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  verify_csrf(); $action=$_POST['action']??'';
  if($action==='create_class'){
   require_teacher(); $title=trim((string)($_POST['title']??'')); $desc=trim((string)($_POST['description']??'')); $starts=trim((string)($_POST['starts_at']??''));
   if($title===''||mb_strlen($title)>200)throw new InvalidArgumentException('عنوان کلاس را وارد کنید.');
   if($hasStarts){$ts=strtotime($starts);if(!$ts||$ts<time()-60)throw new InvalidArgumentException('زمان کلاس را درست وارد کنید.');}else{$ts=time();}
   do{$code=strtoupper(bin2hex(random_bytes(4)));$q=$pdo->prepare('SELECT id FROM classes WHERE room_code=?');$q->execute([$code]);}while($q->fetch());
   $exp=date('Y-m-d H:i:s',$ts+3600);
   if($hasStarts)$q=$pdo->prepare("INSERT INTO classes(teacher_id,title,description,room_code,status,starts_at,expires_at) VALUES(?,?,?,?, 'scheduled',?,?)");
   else $q=$pdo->prepare("INSERT INTO classes(teacher_id,title,description,room_code,status,expires_at) VALUES(?,?,?,?, 'scheduled',?)");
   $hasStarts?$q->execute([$user['id'],$title,$desc?:null,$code,date('Y-m-d H:i:s',$ts),$exp]):$q->execute([$user['id'],$title,$desc?:null,$code,$exp]); redirect('/panel');
  }
  if($action==='create_student'){
   require_teacher();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$pass=(string)($_POST['password']??'');
   if(mb_strlen($name)<2||mb_strlen($name)>100)throw new InvalidArgumentException('نام دانش‌آموز معتبر نیست.');
   if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('ایمیل معتبر نیست.');
   if(strlen($pass)<8)throw new InvalidArgumentException('رمز عبور باید حداقل ۸ کاراکتر باشد.');
   $q=$pdo->prepare('SELECT id FROM users WHERE email=?');$q->execute([$email]);if($q->fetch())throw new InvalidArgumentException('این ایمیل قبلاً ثبت شده است.');
   $pdo->prepare("INSERT INTO users(name,email,password,role,created_at,updated_at) VALUES(?,?,?,'student',NOW(),NOW())")->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$success='دانش‌آموز ساخته شد.';
  }
  if($action==='delete_class'){require_teacher();$id=(int)($_POST['class_id']??0);$q=$user['role']==='admin'?$pdo->prepare('DELETE FROM classes WHERE id=?'):$pdo->prepare('DELETE FROM classes WHERE id=? AND teacher_id=?');$user['role']==='admin'?$q->execute([$id]):$q->execute([$id,$user['id']]);redirect('/panel');}
  if(in_array($action,['approve_request','reject_request'],true)){
   require_teacher();if(!$hasRequests)throw new RuntimeException('جدول درخواست‌ها ساخته نشده است.');$rid=(int)($_POST['request_id']??0);
   $q=$pdo->prepare("SELECT r.*,c.teacher_id,c.title FROM class_join_requests r JOIN classes c ON c.id=r.class_id WHERE r.id=? LIMIT 1");$q->execute([$rid]);$r=$q->fetch();if(!$r)throw new InvalidArgumentException('درخواست پیدا نشد.');
   if($user['role']!=='admin'&&(int)$r['teacher_id']!==(int)$user['id'])throw new RuntimeException('دسترسی ندارید.');
   if($action==='approve_request'){$pdo->beginTransaction();$pdo->prepare("UPDATE class_join_requests SET status='approved',decided_at=NOW(),decided_by=?,reject_reason=NULL WHERE id=?")->execute([$user['id'],$rid]);$pdo->prepare("INSERT INTO class_participants(class_id,user_id,role,joined_at,left_at,created_at,updated_at) VALUES(?,?, 'student',NOW(),NULL,NOW(),NOW()) ON DUPLICATE KEY UPDATE joined_at=NOW(),left_at=NULL,role='student',updated_at=NOW()")->execute([(int)$r['class_id'],(int)$r['user_id']]);$pdo->commit();$success='درخواست تأیید شد.';}
   else{$pdo->prepare("UPDATE class_join_requests SET status='rejected',decided_at=NOW(),decided_by=? WHERE id=?")->execute([$user['id'],$rid]);$success='درخواست رد شد.';}
  }
 }catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'عملیات انجام نشد.';}
}
$classes=[];
if(in_array($user['role'],['teacher','admin'],true)){
 $order=$hasStarts?'COALESCE(c.starts_at,c.created_at)':'c.created_at';
 $q=$user['role']==='admin'?$pdo->query("SELECT c.*,u.name teacher_name FROM classes c JOIN users u ON u.id=c.teacher_id ORDER BY $order DESC"): $pdo->prepare("SELECT c.*,u.name teacher_name FROM classes c JOIN users u ON u.id=c.teacher_id WHERE c.teacher_id=? ORDER BY $order DESC");
 if($user['role']!=='admin')$q->execute([$user['id']]);$classes=$q->fetchAll();
}else{$q=$pdo->prepare("SELECT c.*,cp.joined_at,u.name teacher_name FROM class_participants cp JOIN classes c ON c.id=cp.class_id JOIN users u ON u.id=c.teacher_id WHERE cp.user_id=? AND cp.left_at IS NULL ORDER BY ".($hasStarts?'COALESCE(c.starts_at,c.created_at)':'c.created_at')." DESC");$q->execute([$user['id']]);$classes=$q->fetchAll();}
$requests=[];
if($hasRequests&&in_array($user['role'],['teacher','admin'],true)){$q=$user['role']==='admin'?$pdo->query("SELECT r.*,c.title,c.room_code,u.name student_name,u.email student_email FROM class_join_requests r JOIN classes c ON c.id=r.class_id JOIN users u ON u.id=r.user_id WHERE r.status='pending' ORDER BY r.requested_at DESC"): $pdo->prepare("SELECT r.*,c.title,c.room_code,u.name student_name,u.email student_email FROM class_join_requests r JOIN classes c ON c.id=r.class_id JOIN users u ON u.id=r.user_id WHERE c.teacher_id=? AND r.status='pending' ORDER BY r.requested_at DESC");if($user['role']!=='admin')$q->execute([$user['id']]);$requests=$q->fetchAll();}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>پنل | کاداد کلاس</title><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;600;700;800;900&display=swap" rel="stylesheet"><style>:root{--p:#635bff;--t:#101828;--m:#667085;--b:#eaecf0;--bg:#f6f7fb}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--t);font-family:Vazirmatn,Tahoma,sans-serif}.top{height:76px;background:#fff;border-bottom:1px solid var(--b);display:flex;justify-content:space-between;align-items:center;padding:0 max(20px,calc((100% - 1180px)/2))}.brand{display:flex;gap:10px;align-items:center;text-decoration:none;color:var(--t);font-weight:900}.logo{width:42px;height:42px;border-radius:13px;display:grid;place-items:center;color:#fff;background:linear-gradient(135deg,#766cff,#5148e8)}.user{display:flex;gap:12px;align-items:center;color:var(--m);font-size:13px}.logout,.btn{border:0;border-radius:10px;padding:10px 13px;font:800 12px Vazirmatn;cursor:pointer}.logout{background:#f2f4f7}.btn{background:var(--p);color:#fff}.danger{background:#fff1f2;color:#be123c}.container{width:min(1180px,calc(100% - 40px));margin:32px auto}.hero{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.hero h1{margin:0 0 6px;font-size:29px}.hero p{margin:0;color:var(--m)}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px}.card{background:#fff;border:1px solid var(--b);border-radius:18px;padding:20px;box-shadow:0 7px 25px rgba(16,24,40,.05);margin-bottom:18px}.card h2{font-size:19px;margin:0 0 16px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.full{grid-column:1/-1}label{font-size:12px;font-weight:800;display:block;margin-bottom:6px}input,textarea{width:100%;border:1px solid var(--b);border-radius:11px;padding:10px 12px;font:inherit}textarea{min-height:75px}.msg{padding:11px 13px;border-radius:11px;margin-bottom:12px;font-size:13px}.err{background:#fff1f2;color:#be123c}.ok{background:#ecfdf3;color:#027a48}.info{background:#eff6ff;color:#1d4ed8}.class-title{margin:0 0 6px;font-size:17px}.muted{color:var(--m);font-size:12px;line-height:1.9}.code{display:inline-block;background:#f2f4ff;color:#5148e8;border-radius:8px;padding:5px 8px;font-weight:900;letter-spacing:2px;margin:10px 0}.actions{display:flex;gap:8px;flex-wrap:wrap}.request{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:12px 0;border-bottom:1px solid var(--b)}.request:last-child{border-bottom:0}.request b{display:block}.request small{color:var(--m)}@media(max-width:650px){.hero{align-items:flex-start;flex-direction:column;gap:12px}.fields{grid-template-columns:1fr}.full{grid-column:auto}.user span{display:none}}</style></head><body><header class="top"><a class="brand" href="/panel"><span class="logo">ک</span><span>کاداد کلاس</span></a><div class="user"><span><?=h($user['name'])?> · <?=h(role_label($user['role']))?></span><form method="post" action="/login/logout.php"><button class="logout">خروج</button></form></div></header><main class="container"><section class="hero"><div><h1>سلام <?=h($user['name'])?> 👋</h1><p><?= $user['role']==='student'?'کلاس‌های تأییدشده و زمان آن‌ها را اینجا می‌بینی.':'کلاس‌ها، دانش‌آموزها و درخواست‌های ورود را مدیریت کن.' ?></p></div></section><?php if($error):?><div class="msg err"><?=h($error)?></div><?php endif;?><?php if($success):?><div class="msg ok"><?=h($success)?></div><?php endif;?><?php if(in_array($user['role'],['teacher','admin'],true)):?><section class="card"><h2>ساخت کلاس 🎓</h2><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="create_class"><div class="fields"><div><label>عنوان کلاس</label><input name="title" required maxlength="200" placeholder="مثلاً ریاضی دهم"></div><?php if($hasStarts):?><div><label>زمان شروع</label><input type="datetime-local" name="starts_at" required></div><?php endif;?><div class="full"><label>توضیح</label><textarea name="description" placeholder="توضیح کوتاه کلاس"></textarea></div></div><button class="btn" style="margin-top:13px">ساخت کلاس</button></form></section><section class="card"><h2>ساخت حساب دانش‌آموز 👨‍🎓</h2><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="create_student"><div class="fields"><div><label>نام</label><input name="name" required></div><div><label>ایمیل</label><input name="email" type="email" required></div><div><label>رمز عبور</label><input name="password" type="password" minlength="8" required></div></div><button class="btn" style="margin-top:13px">ساخت دانش‌آموز</button></form></section><?php if($hasRequests):?><section class="card"><h2>درخواست‌های ورود ⏳</h2><?php if(!$requests):?><div class="muted">درخواست معلقی وجود ندارد.</div><?php else:foreach($requests as $r):?><div class="request"><div><b><?=h($r['student_name'])?></b><small><?=h($r['student_email'])?> · <?=h($r['title'])?></small></div><div class="actions"><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="approve_request"><input type="hidden" name="request_id" value="<?=$r['id']?>"><button class="btn">تأیید</button></form><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="reject_request"><input type="hidden" name="request_id" value="<?=$r['id']?>"><button class="btn danger">رد</button></form></div></div><?php endforeach;endif;?></section><?php endif;endif;?><section><h2 style="font-size:20px;margin:22px 0 14px"><?= $user['role']==='student'?'کلاس‌های من':'کلاس‌ها' ?></h2><div class="grid"><?php if(!$classes):?><div class="card muted">هنوز کلاسی وجود ندارد.</div><?php else:foreach($classes as $c):?><article class="card"><h3 class="class-title"><?=h($c['title'])?></h3><?php if(!empty($c['teacher_name'])):?><div class="muted">مدرس: <?=h($c['teacher_name'])?></div><?php endif;?><div class="code"><?=h($c['room_code'])?></div><div class="muted">🕐 زمان: <?=h(dt($c['starts_at']??null))?><br>وضعیت: <?=h($c['status'])?><br>پایان ورود: <?=h(dt($c['expires_at']??null))?></div><div class="actions" style="margin-top:12px"><a class="btn" href="/join/?code=<?=rawurlencode($c['room_code'])?>" style="text-decoration:none">ورود به کلاس</a><?php if(in_array($user['role'],['teacher','admin'],true)):?><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete_class"><input type="hidden" name="class_id" value="<?=$c['id']?>"><button class="btn danger">حذف</button></form><?php endif;?></div></article><?php endforeach;endif;?></div></section></main></body></html>
